915	  /// An iterator for DICompileUnits that skips those marked NoDebug.
916	  class debug_compile_units_iterator {
917	    NamedMDNode *CUs;
918	    unsigned Idx;
919	
920	    LLVM_ABI void SkipNoDebugCUs();
921	
922	  public:
923	    using iterator_category = std::input_iterator_tag;
924	    using value_type = DICompileUnit *;
925	    using difference_type = std::ptrdiff_t;
926	    using pointer = value_type *;
927	    using reference = value_type &;
928	
929	    explicit debug_compile_units_iterator(NamedMDNode *CUs, unsigned Idx)
930	        : CUs(CUs), Idx(Idx) {
931	      SkipNoDebugCUs();
932	    }
933	
934	    debug_compile_units_iterator &operator++() {
935	      ++Idx;
936	      SkipNoDebugCUs();
937	      return *this;
938	    }
939	
940	    debug_compile_units_iterator operator++(int) {
941	      debug_compile_units_iterator T(*this);
942	      ++Idx;
943	      return T;
944	    }
945	
946	    bool operator==(const debug_compile_units_iterator &I) const {
947	      return Idx == I.Idx;
948	    }
949	
950	    bool operator!=(const debug_compile_units_iterator &I) const {
951	      return Idx != I.Idx;
952	    }
953	
954	    LLVM_ABI DICompileUnit *operator*() const;
955	    LLVM_ABI DICompileUnit *operator->() const;
956	  };
