867	static void addSDKVersionMD(const VersionTuple &V, Module &M, StringRef Name) {
868	  SmallVector<unsigned, 3> Entries;
869	  Entries.push_back(V.getMajor());
870	  if (auto Minor = V.getMinor()) {
871	    Entries.push_back(*Minor);
872	    if (auto Subminor = V.getSubminor())
873	      Entries.push_back(*Subminor);
874	    // Ignore the 'build' component as it can't be represented in the object
875	    // file.
876	  }
877	  M.addModuleFlag(Module::ModFlagBehavior::Warning, Name,
878	                  ConstantDataArray::get(M.getContext(), Entries));
879	}
