881	void Module::setSDKVersion(const VersionTuple &V) {
882	  addSDKVersionMD(V, *this, "SDK Version");
883	}
884	
885	static VersionTuple getSDKVersionMD(Metadata *MD) {
886	  auto *CM = dyn_cast_or_null<ConstantAsMetadata>(MD);
887	  if (!CM)
888	    return {};
889	  auto *Arr = dyn_cast_or_null<ConstantDataArray>(CM->getValue());
890	  if (!Arr)
891	    return {};
892	  auto getVersionComponent = [&](unsigned Index) -> std::optional<unsigned> {
893	    if (Index >= Arr->getNumElements())
894	      return std::nullopt;
895	    return (unsigned)Arr->getElementAsInteger(Index);
896	  };
897	  auto Major = getVersionComponent(0);
898	  if (!Major)
899	    return {};
900	  VersionTuple Result = VersionTuple(*Major);
901	  if (auto Minor = getVersionComponent(1)) {
902	    Result = VersionTuple(*Major, *Minor);
903	    if (auto Subminor = getVersionComponent(2)) {
904	      Result = VersionTuple(*Major, *Minor, *Subminor);
905	    }
906	  }
907	  return Result;
908	}
909	
910	VersionTuple Module::getSDKVersion() const {
911	  return getSDKVersionMD(getModuleFlag("SDK Version"));
912	}
