914	GlobalVariable *llvm::collectUsedGlobalVariables(
915	    const Module &M, SmallVectorImpl<GlobalValue *> &Vec, bool CompilerUsed) {
916	  const char *Name = CompilerUsed ? "llvm.compiler.used" : "llvm.used";
917	  GlobalVariable *GV = M.getGlobalVariable(Name);
918	  if (!GV || !GV->hasInitializer())
919	    return GV;
920	
921	  const ConstantArray *Init = cast<ConstantArray>(GV->getInitializer());
922	  for (Value *Op : Init->operands()) {
923	    GlobalValue *G = cast<GlobalValue>(Op->stripPointerCasts());
924	    Vec.push_back(G);
925	  }
926	  return GV;
927	}
